function compute_N_IL2_CD8_division_generations_castro2012(params, inputs)
    N = params["N_IL2_CD8"]
    fold_increase = 2.0 ^ N
    return fold_increase
end

function compute_k_C1_growth_pdac_human_vdt_ahn2017(params, inputs)
    k = params["k_C1_growth"]
    vdt = log(2) / k
    return vdt  # days
end

function compute_k_C1_growth_pdac_tumor_doubling_jang2015(params, inputs)
    k = params["k_C1_growth"]  # 1/day
    return log(2) / k  # in days
end


# Forward model (batch_accumulation)
function compute_k_CCL2_sec_Fujita2010_PrSC(params, inputs, reference_values)
    sec_rate = params["k_CCL2_sec"]
    cells = inputs["n_cells_prsc"]
    t_inc = inputs["incubation_time_hours"]
    mw = reference_values["ccl2_molecular_weight_mature"]
    ucf = 41.6667
    vol = inputs["V_medium_ml"]
    return sec_rate * cells * t_inc * mw * ucf / vol
end

function simulate_k_CCL2_sec_Fujita2010_PrSC(k_CCL2_sec)
    params = Dict("k_CCL2_sec" => k_CCL2_sec)
    inputs = Dict("CCL2_prsc_unstim_mean" => 1888.0, "CCL2_prsc_unstim_sd" => 631.0, "n_cells_prsc" => 100000.0, "incubation_time_hours" => 48.0, "V_medium_ml" => 1.0)
    reference_values = Dict("ccl2_molecular_weight_mature" => 8679.0)
    return compute_k_CCL2_sec_Fujita2010_PrSC(params, inputs, reference_values)
end


