# Forward model (steady_state_concentration)
function compute_k_CCL2_sec_pdac_plasma_Nixon2013(params, inputs, reference_values)
    sec_rate = params["k_CCL2_sec"]
    ucf = 1.0
    source = reference_values["pdac_total_tumor_cells"]
    clearance = params["k_CCL2_deg"]
    vol = reference_values["blood_volume"]
    return sec_rate * ucf * source / (clearance * vol)
end

