function compute_k_M1_pol_rp182_m2_to_m1_repolarization(params::Dict, inputs::Dict)
    k = params["k_M1_pol"]
    # Stimulation time in days (stored directly in inputs)
    t = inputs["rp182_t_30min"]
    f0 = inputs["rp182_cd86pos_cd206pos_frac_vehicle"]
    frac = 1.0 - (1.0 - f0) * exp(-k * t)
    return frac
end


# Forward model (steady_state_ratio)
function compute_k_M1_pol_pdac_cd86_cd163_gu2023(params, inputs)
    r_num = params["k_M1_pol"]
    ucf = 1.0
    r_den = params["k_M2_pol"]
    d_num = 1.0
    d_den = 1.0
    return r_num * ucf * d_num / (r_den * d_den)
end

