function compute_k_MDSC_rec_panc02_spleenexpansion_ghansah2013(params, inputs)
    # k_MDSC_rec: recruitment rate into the spleen surrogate compartment (cell/(milliliter*day))
    k_rec = params["k_MDSC_rec"]
    f0 = inputs["mdsc_fraction_baseline"]
    t = inputs["observation_time_day27"]
    rho = inputs["spleen_cell_density"]
    # Predicted MDSC fraction at time t assuming linear accumulation
    return f0 + (k_rec * t / rho)
end


