# Analytical solution for first-order decay: du/dt = -k*u => u(t) = u₀ * exp(-k*t)
function simulate_k_apsc_death_melatoninPSC_Estaras2021(k_apsc_death)
    d = DATA["k_apsc_death_melatoninPSC_Estaras2021"]
