# N_IL2_CD4_division_destiny_Gett1998
@model function calibrate_N_IL2_CD4_division_destiny_Gett1998(data)
    # Priors
    N_IL2_CD4 ~ Normal(8.0, 2.0)

    # Forward model
    params = Dict("N_IL2_CD4" => N_IL2_CD4)
    inputs = data["N_IL2_CD4_division_destiny_Gett1998"].inputs
    pred = compute_N_IL2_CD4_division_destiny_Gett1998(params, inputs)

    # Likelihood
    data["N_IL2_CD4_division_destiny_Gett1998"].obs_median[1] ~ Normal(pred, data["N_IL2_CD4_division_destiny_Gett1998"].obs_sigma[1])

    return (N_IL2_CD4=N_IL2_CD4)
end

